      if (err.keyword === 'type' && 'type' in err.params) {
        if (!fieldName) {
          const schemaPath = (err.schemaPath as string) || '';
          const match = schemaPath.match(/#\/properties\/([^\/]+)/);
          fieldName = match ? match[1] : 'unknown field';
        }
        return `Field '${fieldName}' must be of type ${(err.params as {type: string}).type}`;
      }
      return `Validation failed at ${fieldName || 'unknown'}: ${err.message}`;
    });
    const resultMessage = errorMessages.join('; ');
    log.info('tool', 'schema validation failed', {name, validationError: resultMessage});
    return {result: resultMessage};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);
  const response = normalizeToolResponse(rawResult);
  log.info('tool', 'execution complete', {
    name,
    rawType: typeof rawResult,
    clientMessageCount: response.clientMessages?.length ?? 0,
    clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
    suppressAssistantResponse: response.suppressAssistantResponse ?? false,
  });
  return response;
